/* ==========================================================================
   rull.ai.id — ASCII Hermes 3D
   Relief 140 x 108 (depth + albedo di-bake dari alt-statue-hermes-blue-800.jpg)
   Inverse relief mapping (ray-march heightfield) => tanpa lubang piksel saat
   diputar, plus pencahayaan dinamis dari normal dz/dx, dz/dy.
   Output: 3 layer <pre> (navy / periwinkle / putih) lewat text node (tanpa innerHTML).
   ========================================================================== */
(function () {
  "use strict";

  var A_B64 = "";
  var H_B64 = "";
  var W_B64 = "";

  var stage = document.getElementById("ascii-stage");
  if (!stage) return;
  var frame = stage.parentElement;
  var layerEls = stage.querySelectorAll(".ascii-layer");
  if (layerEls.length !== 3) return;
  var fallback = stage.querySelector(".ascii-fallback");
  var btn = frame.querySelector(".ascii-live-btn");
  var btnLabel = btn ? btn.querySelector(".ascii-live-label") : null;

  var COLS = parseInt(frame.getAttribute("data-cols"), 10) || 140;
  var ROWS = parseInt(frame.getAttribute("data-rows"), 10) || 108;
  var N = COLS * ROWS;
  var ASPECT = 1.25; /* tinggi frame / lebar frame (4:5) */

  var ZMAX = 0.15;   /* kedalaman maksimum relief (satuan lebar frame) */
  var ZC = 0.075;    /* pivot rotasi */
  var STEPS = 14;
  var BG = 0.34;     /* level nada latar (cobalt) pada albedo */
  var FPS = 28;
  var RAD = Math.PI / 180;

  /* ---------- data ---------- */
  function decode(b64) {
    var bin = atob(b64);
    var out = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }
  var aRaw = decode(A_B64);
  var hRaw = decode(H_B64);
  var wRaw = decode(W_B64);
  if (aRaw.length !== N || hRaw.length !== N || wRaw.length !== N) return;

  var Af = new Float32Array(N);
  var Hf = new Float32Array(N);
  var NX = new Float32Array(N);
  var NY = new Float32Array(N);
  var NZ = new Float32Array(N);
  var RIM = new Float32Array(N);
  var BASE = new Float32Array(N);
  var i, j, k;
  for (k = 0; k < N; k++) {
    Af[k] = aRaw[k] / 255;
    Hf[k] = (hRaw[k] / 255) * ZMAX;
  }

  var cellW = 1 / COLS;
  var cellH = ASPECT / ROWS;
  function hAt(ci, cj) {
    ci = ci < 0 ? 0 : ci >= COLS ? COLS - 1 : ci;
    cj = cj < 0 ? 0 : cj >= ROWS ? ROWS - 1 : cj;
    return Hf[cj * COLS + ci];
  }

  /* cahaya netral = tampilan "statis" asli; cahaya dinamis hanya menambah selisihnya */
  var L0x = -0.45, L0y = -0.5, L0z = 0.62;
  var l0 = Math.sqrt(L0x * L0x + L0y * L0y + L0z * L0z);
  L0x /= l0; L0y /= l0; L0z /= l0;
  var SPEC_POW = 16;

  for (j = 0; j < ROWS; j++) {
    for (i = 0; i < COLS; i++) {
      var dx = (hAt(i + 1, j) - hAt(i - 1, j)) / (2 * cellW);
      var dy = (hAt(i, j + 1) - hAt(i, j - 1)) / (2 * cellH);
      var nx = -dx, ny = -dy, nz = 1;
      var nl = Math.sqrt(nx * nx + ny * ny + nz * nz);
      nx /= nl; ny /= nl; nz /= nl;
      var idx = j * COLS + i;
      NX[idx] = nx; NY[idx] = ny; NZ[idx] = nz;
      var h = Hf[idx] / ZMAX;
      RIM[idx] = (h > 0.1 ? 1 : h / 0.1) * (wRaw[idx] / 255);
      BASE[idx] = L0x * nx + L0y * ny + L0z * nz;
    }
  }

  var XS = new Float32Array(COLS);
  var YS = new Float32Array(ROWS);
  for (i = 0; i < COLS; i++) XS[i] = (i + 0.5) / COLS - 0.5;
  for (j = 0; j < ROWS; j++) YS[j] = ((j + 0.5) / ROWS - 0.5) * ASPECT;

  var BAYER = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5];
  var DITHER = new Float32Array(16);
  for (k = 0; k < 16; k++) DITHER[k] = ((BAYER[k] + 0.5) / 16 - 0.5) * 0.02;

  var RAMP = [32, 46, 58, 59, 43, 42, 111, 79, 35, 37, 64]; /* ' .:;+*oO#%@' */

  function bil(arr, u, v) {
    if (u < 0) u = 0; else if (u > COLS - 1.001) u = COLS - 1.001;
    if (v < 0) v = 0; else if (v > ROWS - 1.001) v = ROWS - 1.001;
    var x0 = u | 0, y0 = v | 0;
    var fx = u - x0, fy = v - y0;
    var o = y0 * COLS + x0;
    var a = arr[o], b = arr[o + 1], c = arr[o + COLS], d = arr[o + COLS + 1];
    return (a + (b - a) * fx) * (1 - fy) + (c + (d - c) * fx) * fy;
  }

  /* ---------- buffer teks & node ---------- */
  var LINE = COLS + 1;
  var bufs = [new Uint8Array(LINE * ROWS), new Uint8Array(LINE * ROWS), new Uint8Array(LINE * ROWS)];
  var nodes = [];
  var decoder = typeof TextDecoder === "function" ? new TextDecoder("latin1") : null;
  for (k = 0; k < 3; k++) {
    layerEls[k].textContent = "";
    var tn = document.createTextNode("");
    layerEls[k].appendChild(tn);
    nodes.push(tn);
  }
  function bufToString(buf) {
    if (decoder) return decoder.decode(buf);
    var s = "";
    for (var o = 0; o < buf.length; o += 4096) s += String.fromCharCode.apply(null, buf.subarray(o, o + 4096));
    return s;
  }

  /* ---------- render ---------- */
  function render(yaw, pitch, lx, ly) {
    var cy = Math.cos(yaw), sy = Math.sin(yaw), cp = Math.cos(pitch), sp = Math.sin(pitch);
    var R00 = cy, R01 = 0, R02 = sy;
    var R10 = sp * sy, R11 = cp, R12 = -sp * cy;
    var R20 = -cp * sy, R21 = sp, R22 = cp * cy;

    var Lx = lx, Ly = ly, Lz = 0.62;
    var ll = Math.sqrt(Lx * Lx + Ly * Ly + Lz * Lz);
    Lx /= ll; Ly /= ll; Lz /= ll;
    var Hx = Lx, Hy = Ly, Hz = Lz + 1;
    var hl = Math.sqrt(Hx * Hx + Hy * Hy + Hz * Hz);
    Hx /= hl; Hy /= hl; Hz /= hl;
    var hb0x = L0x, hb0y = L0y, hb0z = L0z + 1;
    var hb0 = Math.sqrt(hb0x * hb0x + hb0y * hb0y + hb0z * hb0z);
    hb0x /= hb0; hb0y /= hb0; hb0z /= hb0;

    var tx = R20, ty = R21, tz = R22;
    var dz = ZMAX / STEPS;
    var ds = dz / tz;

    var b0 = bufs[0], b1 = bufs[1], b2 = bufs[2];
    b0.fill(32); b1.fill(32); b2.fill(32);

    for (var j = 0; j < ROWS; j++) {
      var y = YS[j];
      var rowO = j * LINE;
      b0[rowO + COLS] = 10; b1[rowO + COLS] = 10; b2[rowO + COLS] = 10;
      for (var i = 0; i < COLS; i++) {
        var x = XS[i];
        var p0x = R00 * x + R10 * y - R20 * ZC;
        var p0y = R01 * x + R11 * y - R21 * ZC;
        var p0z = R02 * x + R12 * y - R22 * ZC + ZC;
        var s0 = (ZMAX - p0z) / tz;

        var dPrev = 0, pcx = 0, pcy = 0, hx = 0, hy = 0;
        for (var s = 0; s <= STEPS; s++) {
          var z = ZMAX - s * dz;
          var sv = s0 + s * ds;
          var cx = p0x + sv * tx;
          var cyy = p0y + sv * ty;
          var h = bil(Hf, (cx + 0.5) * COLS - 0.5, (cyy * 0.8 + 0.5) * ROWS - 0.5);
          var d = z - h;
          if (d <= 0) {
            if (s > 0) {
              var a = dPrev / (dPrev - d);
              hx = pcx + a * (cx - pcx);
              hy = pcy + a * (cyy - pcy);
            } else {
              hx = cx; hy = cyy;
            }
            break;
          }
          dPrev = d; pcx = cx; pcy = cyy;
          hx = cx; hy = cyy;
        }

        var u = (hx + 0.5) * COLS - 0.5;
        var v = (hy * 0.8 + 0.5) * ROWS - 0.5;
        var val = bil(Af, u, v);

        var ui = Math.round(u), vi = Math.round(v);
        ui = ui < 0 ? 0 : ui >= COLS ? COLS - 1 : ui;
        vi = vi < 0 ? 0 : vi >= ROWS ? ROWS - 1 : vi;
        var idx = vi * COLS + ui;
        var rim = RIM[idx];
        if (rim > 0) {
          var nx = NX[idx], ny = NY[idx], nz = NZ[idx];
          var vx = R00 * nx + R01 * ny + R02 * nz;
          var vy = R10 * nx + R11 * ny + R12 * nz;
          var vz = R20 * nx + R21 * ny + R22 * nz;
          var lam = Lx * vx + Ly * vy + Lz * vz;
          var sd = Hx * vx + Hy * vy + Hz * vz;
          var sb = hb0x * nx + hb0y * ny + hb0z * nz;
          var spec = (sd > 0 ? Math.pow(sd, SPEC_POW) : 0) - (sb > 0 ? Math.pow(sb, SPEC_POW) : 0);
          var dl = 0.4 * (lam - BASE[idx]) + 0.14 * spec;
          dl = dl < -0.26 ? -0.26 : dl > 0.26 ? 0.26 : dl;
          val += rim * dl;
        }

        var layer, dens;
        if (val < BG) { layer = 0; dens = (BG - val) / BG; }
        else if (val < 0.68) { layer = 1; dens = (val - BG) / 0.34; }
        else { layer = 2; dens = 0.15 + 0.85 * Math.min(1, (val - 0.68) / 0.32); }
        dens += DITHER[(i & 3) + ((j & 3) << 2)];
        var ci = (dens * 10 + 0.5) | 0;
        if (ci <= 0) continue;
        if (ci > 10) ci = 10;
        (layer === 0 ? b0 : layer === 1 ? b1 : b2)[rowO + i] = RAMP[ci];
      }
    }

    nodes[0].data = bufToString(b0);
    nodes[1].data = bufToString(b1);
    nodes[2].data = bufToString(b2);
  }

  /* ---------- fit font ke lebar frame ---------- */
  var measureCtx = document.createElement("canvas").getContext("2d");
  var probeEl = null;
  function getProbe() {
    if (probeEl) return probeEl;
    probeEl = document.createElement("pre");
    probeEl.className = "ascii-layer";
    probeEl.setAttribute("aria-hidden", "true");
    probeEl.style.position = "absolute";
    probeEl.style.visibility = "hidden";
    probeEl.style.left = "0";
    probeEl.style.top = "0";
    probeEl.style.right = "auto";
    probeEl.style.bottom = "auto";
    probeEl.style.inset = "auto";
    probeEl.style.width = "auto";
    probeEl.style.height = "auto";
    probeEl.style.overflow = "visible";
    probeEl.style.contain = "none";
    probeEl.style.transform = "none";
    probeEl.textContent = new Array(COLS + 1).join("M");
    return probeEl;
  }

  function applyLayerTransform(sx, sy) {
    var val = (sx === 1 && sy === 1)
      ? "none"
      : (sy === 1 ? "scaleX(" + sx.toFixed(6) + ")" : "scale(" + sx.toFixed(6) + ", " + sy.toFixed(6) + ")");
    var lw = sx < 1 ? (100 / sx).toFixed(4) + "%" : "";
    var lh = sy < 1 ? (100 / sy).toFixed(4) + "%" : "";
    for (var m = 0; m < layerEls.length; m++) {
      layerEls[m].style.transform = val;
      layerEls[m].style.right = sx < 1 ? "auto" : "";
      layerEls[m].style.bottom = sy < 1 ? "auto" : "";
      layerEls[m].style.width = lw;
      layerEls[m].style.height = lh;
    }
  }

  function fit() {
    var width = stage.clientWidth;
    var height = stage.clientHeight;
    if (!width || !height) return;

    var fs = 0;
    if (measureCtx) {
      var family = getComputedStyle(layerEls[0]).fontFamily;
      measureCtx.font = "700 100px " + family;
      var advance = measureCtx.measureText("MMMMMMMMMM").width / 10 / 100;
      if (advance > 0) fs = (width / (COLS * advance)) * 0.998;
    }
    if (!(fs > 0)) fs = (width / (COLS * 0.6)) * 0.998;

    var lh = (height / ROWS) * 0.997;
    stage.style.setProperty("--ascii-fs", fs.toFixed(4) + "px");
    stage.style.setProperty("--ascii-lh", lh.toFixed(4) + "px");

    var probe = getProbe();
    if (!probe.parentNode) stage.appendChild(probe);

    var measuredWidth = probe.getBoundingClientRect().width;
    if (measuredWidth > 0) {
      fs = fs * (width / measuredWidth) * 0.997;
      stage.style.setProperty("--ascii-fs", fs.toFixed(4) + "px");
    }

    var rect2 = probe.getBoundingClientRect();
    var measuredWidth2 = rect2.width;
    var measuredLineH = rect2.height;

    if (measuredLineH > 0) {
      var targetLineH = (height / ROWS) * 0.997;
      var adjustedLh = lh * (targetLineH / measuredLineH);
      if (isFinite(adjustedLh) && adjustedLh > 0) {
        lh = adjustedLh;
        stage.style.setProperty("--ascii-lh", lh.toFixed(4) + "px");
        measuredLineH = probe.getBoundingClientRect().height;
      }
    }

    var scaleX = 1;
    var scaleY = 1;
    if (measuredWidth2 > width * 1.005) {
      scaleX = width / measuredWidth2;
    }
    if (measuredLineH > 0 && measuredLineH * ROWS > height * 1.005) {
      scaleY = height / (measuredLineH * ROWS);
    }

    applyLayerTransform(scaleX, scaleY);

    if (probe.parentNode) stage.removeChild(probe);
  }

  /* ---------- state & animasi ---------- */
  var reduceQuery = window.matchMedia ? window.matchMedia("(prefers-reduced-motion: reduce)") : null;
  var playing = !(reduceQuery && reduceQuery.matches);
  var inView = true;
  var raf = 0;
  var lastFrame = 0;
  var lastTick = 0;
  var time = 0;

  var st = { yaw: 0, pitch: 0, lx: L0x, ly: L0y, act: 0 };
  var ptr = { x: 0, y: 0, on: false };

  function target(t) {
    var yawA = 14 * RAD * Math.sin(t * 0.85);
    var pitchA = 7 * RAD * Math.sin(t * 0.6 + 0.9);
    var lxA = L0x + 0.55 * Math.sin(t * 0.7 + 0.4);
    var lyA = L0y + 0.3 * Math.cos(t * 0.55);
    var a = st.act;
    return {
      yaw: yawA * (1 - a) + (ptr.x * 16 * RAD + yawA * 0.25) * a,
      pitch: pitchA * (1 - a) + (ptr.y * 9 * RAD + pitchA * 0.25) * a,
      lx: lxA * (1 - a) + (ptr.x * 0.7 - 0.2) * a,
      ly: lyA * (1 - a) + (ptr.y * 0.6 - 0.3) * a
    };
  }

  function tick(now) {
    raf = 0;
    if (!playing || !inView || document.hidden) return;
    raf = requestAnimationFrame(tick);
    if (now - lastFrame < 1000 / FPS - 1) return;
    var dt = lastTick ? Math.min((now - lastTick) / 1000, 0.1) : 1 / FPS;
    lastTick = now;
    lastFrame = now;
    time += dt;
    st.act += ((ptr.on ? 1 : 0) - st.act) * (1 - Math.exp(-dt * 5));
    var tg = target(time);
    var f = 1 - Math.exp(-dt * 7);
    st.yaw += (tg.yaw - st.yaw) * f;
    st.pitch += (tg.pitch - st.pitch) * f;
    st.lx += (tg.lx - st.lx) * f;
    st.ly += (tg.ly - st.ly) * f;
    render(st.yaw, st.pitch, st.lx, st.ly);
  }

  function schedule() {
    if (!raf && playing && inView && !document.hidden) {
      lastTick = 0;
      raf = requestAnimationFrame(tick);
    }
  }

  function setPlaying(on) {
    playing = on;
    frame.classList.toggle("is-paused", !on);
    if (btn) {
      btn.setAttribute("aria-pressed", on ? "true" : "false");
      btn.setAttribute("aria-label", on ? "Jeda animasi 3D" : "Putar animasi 3D");
    }
    if (btnLabel) btnLabel.textContent = on ? "LIVE 3D" : "PAUSED";
    if (on) schedule();
    else if (raf) { cancelAnimationFrame(raf); raf = 0; }
  }

  /* ---------- interaksi ---------- */
  function updatePointer(e) {
    var r = frame.getBoundingClientRect();
    if (!r.width || !r.height) return;
    var px = ((e.clientX - r.left) / r.width) * 2 - 1;
    var py = ((e.clientY - r.top) / r.height) * 2 - 1;
    ptr.x = px < -1 ? -1 : px > 1 ? 1 : px;
    ptr.y = py < -1 ? -1 : py > 1 ? 1 : py;
    ptr.on = true;
  }
  function releasePointer() { ptr.on = false; }
  frame.addEventListener("pointermove", updatePointer);
  frame.addEventListener("pointerdown", updatePointer);
  frame.addEventListener("pointerleave", releasePointer);
  frame.addEventListener("pointercancel", releasePointer);
  frame.addEventListener("pointerup", function (e) { if (e.pointerType !== "mouse") releasePointer(); });

  if (btn) btn.addEventListener("click", function () { setPlaying(!playing); });

  document.addEventListener("visibilitychange", schedule);
  if ("IntersectionObserver" in window) {
    new IntersectionObserver(function (entries) {
      inView = entries[entries.length - 1].isIntersecting;
      if (inView) schedule();
    }, { threshold: 0 }).observe(frame);
  }
  if (reduceQuery) {
    var onReduce = function () { if (reduceQuery.matches && playing) setPlaying(false); };
    if (reduceQuery.addEventListener) reduceQuery.addEventListener("change", onReduce);
    else if (reduceQuery.addListener) reduceQuery.addListener(onReduce);
  }

  window.addEventListener("resize", fit);
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(fit);

  fit();
  render(0, 0, L0x, L0y); /* frame netral = tampilan statis asli */
  frame.classList.add("is-3d");
  if (fallback) fallback.setAttribute("hidden", "");
  setPlaying(playing);
})();


